import{_ as a,o as e,c as s,O as r}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"记忆与多智能体","description":"两个问题合在一篇：怎么让它记住（上下文有限、跨会话会忘），和怎么让它分工（一个 Agent 能力有限、串起来又难控）。","frontmatter":{"description":"两个问题合在一篇：怎么让它记住（上下文有限、跨会话会忘），和怎么让它分工（一个 Agent 能力有限、串起来又难控）。","tags":["AI Agent","大模型"]},"headers":[],"relativePath":"backend/AI-Agent/06-记忆与多智能体.md","filePath":"backend/AI-Agent/06-记忆与多智能体.md","lastUpdated":1793245104000}'),n={name:"backend/AI-Agent/06-记忆与多智能体.md"};function d(o,t,l,p,i,h){return e(),s("div",null,t[0]||(t[0]=[r(`<h1 id="记忆与多智能体" tabindex="-1">记忆与多智能体 <a class="header-anchor" href="#记忆与多智能体" aria-label="Permalink to &quot;记忆与多智能体&quot;">​</a></h1><blockquote><p>两个问题合在一篇：<strong>怎么让它记住</strong>（上下文有限、跨会话会忘），和<strong>怎么让它分工</strong>（一个 Agent 能力有限、串起来又难控）。</p></blockquote><h2 id="一、记忆系统" tabindex="-1">一、记忆系统 <a class="header-anchor" href="#一、记忆系统" aria-label="Permalink to &quot;一、记忆系统&quot;">​</a></h2><h3 id="_1-为什么需要「记忆」" tabindex="-1">1. 为什么需要「记忆」 <a class="header-anchor" href="#_1-为什么需要「记忆」" aria-label="Permalink to &quot;1. 为什么需要「记忆」&quot;">​</a></h3><table><thead><tr><th>约束</th><th>后果</th></tr></thead><tbody><tr><td>上下文窗口有限</td><td>聊久了必须丢或压</td></tr><tr><td>每次请求都是无状态的</td><td>换个会话它就忘了你是谁</td></tr><tr><td>长期偏好要跨会话保留</td><td>需要持久化</td></tr></tbody></table><p><strong>记忆的本质是「在有限上下文里，选最该带上的信息」</strong> —— 和 RAG 是同一个问题（检索），只是检索的是「历史」。</p><h3 id="_2-短期记忆-最近几轮" tabindex="-1">2. 短期记忆：最近几轮 <a class="header-anchor" href="#_2-短期记忆-最近几轮" aria-label="Permalink to &quot;2. 短期记忆：最近几轮&quot;">​</a></h3><table><thead><tr><th>策略</th><th>做法</th><th>代价</th></tr></thead><tbody><tr><td>滑动窗口</td><td>只带最近 N 轮</td><td>早期信息丢失（最稳、最常用）</td></tr><tr><td>摘要压缩</td><td>更早的对话压成一段</td><td>多一次模型调用、有损</td></tr><tr><td>混合</td><td>最近 N 轮原文 + 更早的摘要</td><td><strong>推荐</strong></td></tr></tbody></table><p>配一个 <strong>token 预算</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">可用 = 窗口上限 − 预留输出 − 系统提示词 − RAG 片段</span></span>
<span class="line"><span style="color:#e1e4e8;">超了 → 先砍最老的历史 → 再砍 RAG 条数 → 最后重压摘要</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">可用 = 窗口上限 − 预留输出 − 系统提示词 − RAG 片段</span></span>
<span class="line"><span style="color:#24292e;">超了 → 先砍最老的历史 → 再砍 RAG 条数 → 最后重压摘要</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-长期记忆-三种形态" tabindex="-1">3. 长期记忆：三种形态 <a class="header-anchor" href="#_3-长期记忆-三种形态" aria-label="Permalink to &quot;3. 长期记忆：三种形态&quot;">​</a></h3><table><thead><tr><th>形态</th><th>存什么</th><th>实现</th></tr></thead><tbody><tr><td><strong>向量记忆</strong></td><td>历史片段，按语义召回</td><td>存向量库，检索 topK</td></tr><tr><td><strong>结构化画像</strong></td><td>「用户是程序员、在准备考研、讨厌被推销」</td><td>表/JSON，key-value</td></tr><tr><td><strong>事件时间线</strong></td><td>「3 月 2 日说要退款」「3 月 5 日已处理」</td><td>按时间排序的事件表</td></tr></tbody></table><p><strong>三者配合</strong>：画像给「底色」，时间线给「最近发生了什么」，向量给「相关的旧事」。</p><h3 id="_4-写入策略-什么该记" tabindex="-1">4. 写入策略：什么该记 <a class="header-anchor" href="#_4-写入策略-什么该记" aria-label="Permalink to &quot;4. 写入策略：什么该记&quot;">​</a></h3><p>不是所有对话都值得记。判断标准：</p><table><thead><tr><th>该记</th><th>不该记</th></tr></thead><tbody><tr><td>稳定偏好、身份信息（职业、语言）</td><td>一次性的寒暄、语气词</td></tr><tr><td>明确的长期目标</td><td>临时情绪</td></tr><tr><td>关键事实（订单号、约定时间）</td><td>模型的推测</td></tr><tr><td>已发生的动作与结果</td><td>重复信息</td></tr></tbody></table><p>三个必做：</p><ol><li><strong>去重</strong>：同样的偏好不要记 10 遍（写之前先查相似记忆，超阈值就更新而不是新增）；</li><li><strong>冲突处理</strong>：新记忆和旧的矛盾时（「我住北京」→「我搬去上海了」），要<strong>覆盖 + 记变更时间</strong>，别两条都留着；</li><li><strong>遗忘/过期</strong>：给记忆加 TTL 或重要性分数，定期衰减，避免越攒越乱。</li></ol><h3 id="_5-检索记忆-不只是相似度" tabindex="-1">5. 检索记忆：不只是相似度 <a class="header-anchor" href="#_5-检索记忆-不只是相似度" aria-label="Permalink to &quot;5. 检索记忆：不只是相似度&quot;">​</a></h3><p>生成式 Agent 的经典做法是三维加权：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">score = α·相关性 + β·时效性(recency) + γ·重要性(importance)</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">score = α·相关性 + β·时效性(recency) + γ·重要性(importance)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>相关性</strong>：向量相似度；</li><li><strong>时效性</strong>：越近越重要（指数衰减）；</li><li><strong>重要性</strong>：写入时让模型打 1～10 分（「用户说他要考研」比「用户说了句谢谢」重要）。</li></ul><p>只用相似度会出问题：三个月前一句「随便看看」和昨天一句「下周要下单」，语义可能很像。</p><h3 id="_6-隐私与隔离-最容易出事的地方" tabindex="-1">6. 隐私与隔离（最容易出事的地方） <a class="header-anchor" href="#_6-隐私与隔离-最容易出事的地方" aria-label="Permalink to &quot;6. 隐私与隔离（最容易出事的地方）&quot;">​</a></h3><table><thead><tr><th>要求</th><th>做法</th></tr></thead><tbody><tr><td>用户隔离</td><td>记忆按 <code>userId</code> 分库/分区，检索必须带过滤条件</td></tr><tr><td>删除权</td><td>提供「删除我的记忆」，物理删除 + 索引重建</td></tr><tr><td>敏感信息</td><td>手机号、身份证等不入记忆，或加密存储</td></tr><tr><td>审计</td><td>谁在什么时候写入了什么记忆</td></tr><tr><td>跨租户</td><td>永远不要把 A 的记忆检索给 B（这是重大事故）</td></tr></tbody></table><blockquote><p>面试口径：<strong>记忆是用户数据，不是模型参数</strong>。它的隔离、删除、审计要求和业务数据一样严。</p></blockquote><h2 id="二、多智能体系统" tabindex="-1">二、多智能体系统 <a class="header-anchor" href="#二、多智能体系统" aria-label="Permalink to &quot;二、多智能体系统&quot;">​</a></h2><h3 id="_7-为什么要多个-agent" tabindex="-1">7. 为什么要多个 Agent <a class="header-anchor" href="#_7-为什么要多个-agent" aria-label="Permalink to &quot;7. 为什么要多个 Agent&quot;">​</a></h3><table><thead><tr><th>动机</th><th>说明</th></tr></thead><tbody><tr><td><strong>分工专业化</strong></td><td>检索 Agent、写作 Agent、审核 Agent，各自提示词更短更专</td></tr><tr><td><strong>并行</strong></td><td>多个子任务同时跑，缩短总时长</td></tr><tr><td><strong>隔离上下文</strong></td><td>每个 Agent 只看自己那部分，避免上下文爆炸</td></tr><tr><td><strong>可校验</strong></td><td>一个生成、一个审查，比「自己检查自己」更有效</td></tr></tbody></table><h3 id="_8-四种协作模式" tabindex="-1">8. 四种协作模式 <a class="header-anchor" href="#_8-四种协作模式" aria-label="Permalink to &quot;8. 四种协作模式&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">① Supervisor（主管）        ② Pipeline（流水线）</span></span>
<span class="line"><span style="color:#e1e4e8;">    ┌──────────┐              A → B → C</span></span>
<span class="line"><span style="color:#e1e4e8;">    │supervisor│</span></span>
<span class="line"><span style="color:#e1e4e8;">    └──┬───┬───┘              ③ Debate（辩论）</span></span>
<span class="line"><span style="color:#e1e4e8;">   ┌───▼┐ ┌▼───┐                A ⇄ B → 裁决</span></span>
<span class="line"><span style="color:#e1e4e8;">   │ A  │ │ B  │</span></span>
<span class="line"><span style="color:#e1e4e8;">   └────┘ └────┘              ④ Group chat（群聊）</span></span>
<span class="line"><span style="color:#e1e4e8;">                                共享一个消息池，按规则发言</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">① Supervisor（主管）        ② Pipeline（流水线）</span></span>
<span class="line"><span style="color:#24292e;">    ┌──────────┐              A → B → C</span></span>
<span class="line"><span style="color:#24292e;">    │supervisor│</span></span>
<span class="line"><span style="color:#24292e;">    └──┬───┬───┘              ③ Debate（辩论）</span></span>
<span class="line"><span style="color:#24292e;">   ┌───▼┐ ┌▼───┐                A ⇄ B → 裁决</span></span>
<span class="line"><span style="color:#24292e;">   │ A  │ │ B  │</span></span>
<span class="line"><span style="color:#24292e;">   └────┘ └────┘              ④ Group chat（群聊）</span></span>
<span class="line"><span style="color:#24292e;">                                共享一个消息池，按规则发言</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><table><thead><tr><th>模式</th><th>优点</th><th>缺点</th><th>适合</th></tr></thead><tbody><tr><td><strong>Supervisor</strong></td><td>控制力强、易观测</td><td>主管是瓶颈</td><td>任务可分解、需要调度</td></tr><tr><td><strong>Pipeline</strong></td><td>简单、确定</td><td>不能回退</td><td>有固定步骤（写作→审校→格式化）</td></tr><tr><td><strong>Debate</strong></td><td>提升准确性</td><td>成本翻倍</td><td>需要高置信度的判断</td></tr><tr><td><strong>Group chat</strong></td><td>灵活</td><td>难收敛、易跑题</td><td>头脑风暴（慎用于生产）</td></tr></tbody></table><p><strong>生产上最常见的是 Supervisor + Pipeline 的组合</strong>，Debate 用于关键决策点，Group chat 基本只用于演示。</p><h3 id="_9-通信与共享状态" tabindex="-1">9. 通信与共享状态 <a class="header-anchor" href="#_9-通信与共享状态" aria-label="Permalink to &quot;9. 通信与共享状态&quot;">​</a></h3><table><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>共享黑板（blackboard）</strong></td><td>所有 Agent 读写同一个状态对象，最简单</td></tr><tr><td><strong>消息传递</strong></td><td>点对点/发布订阅，解耦但难追踪</td></tr><tr><td><strong>结构化产物</strong></td><td>每个 Agent 输出 JSON，下游只读字段（<strong>最稳</strong>）</td></tr></tbody></table><p>建议：<strong>用结构化产物代替自然语言传话</strong>。「检索 Agent 输出 <code>{docs:[...], confidence:0.8}</code>」比「检索 Agent 说了一段话让写作 Agent 自己理解」可靠得多。</p><h3 id="_10-冲突与收敛" tabindex="-1">10. 冲突与收敛 <a class="header-anchor" href="#_10-冲突与收敛" aria-label="Permalink to &quot;10. 冲突与收敛&quot;">​</a></h3><table><thead><tr><th>问题</th><th>处理</th></tr></thead><tbody><tr><td>两个 Agent 结论矛盾</td><td>第三方裁决（规则/仲裁 Agent/人工）</td></tr><tr><td>无限互相修改</td><td><strong>最大轮次</strong>（2～3 轮）+ 超时就采用最后一版</td></tr><tr><td>责任不清</td><td>每个 Agent 有明确输入输出契约</td></tr><tr><td>成本失控</td><td>每个 Agent 独立的 token 预算</td></tr></tbody></table><h3 id="_11-什么时候不要用多智能体" tabindex="-1">11. 什么时候<strong>不要</strong>用多智能体 <a class="header-anchor" href="#_11-什么时候不要用多智能体" aria-label="Permalink to &quot;11. 什么时候**不要**用多智能体&quot;">​</a></h3><ul><li>单个 Agent + 好工具就能解决；</li><li>延迟敏感（多一次往返就多几百毫秒到几秒）；</li><li>团队没有可观测能力（出问题完全没法查）；</li><li>任务本身是线性的（那叫工作流，不叫多智能体）。</li></ul><blockquote><p>一句实话：<strong>多智能体最大的收益是「上下文隔离」，最大的代价是「调试地狱」</strong>。没有强观测能力之前，别上。</p></blockquote><h2 id="_12-速查表" tabindex="-1">12. 速查表 <a class="header-anchor" href="#_12-速查表" aria-label="Permalink to &quot;12. 速查表&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>记忆的本质</td><td>在有限上下文里检索最该带上的历史</td></tr><tr><td>短期记忆怎么存</td><td>最近 N 轮原文 + 更早的摘要 + token 预算</td></tr><tr><td>长期记忆三种形态</td><td>向量记忆、结构化画像、事件时间线</td></tr><tr><td>什么该记</td><td>稳定偏好、长期目标、关键事实、已发生动作</td></tr><tr><td>冲突记忆怎么办</td><td>覆盖 + 记变更时间，别两条并存</td></tr><tr><td>记忆检索怎么算分</td><td>相关性 + 时效性 + 重要性加权</td></tr><tr><td>记忆最容易出的事故</td><td>跨用户串数据，必须按 userId 强隔离</td></tr><tr><td>多智能体为了什么</td><td>分工、并行、上下文隔离、互相校验</td></tr><tr><td>最常用的协作模式</td><td>Supervisor + Pipeline</td></tr><tr><td>怎么传信息</td><td>结构化产物（JSON），别用自然语言传话</td></tr><tr><td>什么时候别用</td><td>单 Agent 能解、延迟敏感、没观测能力</td></tr></tbody></table>`,43)]))}const g=a(n,[["render",d]]);export{b as __pageData,g as default};
